import assert from "node:assert/strict";
import test from "node:test";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { runAnalysis, verifySources } from "../miners/mine.js";
import { createFirecrawl } from "../firecrawl/client.js";
import { SCRAPE_FIXTURES } from "../firecrawl/client.js";
import type { ResearchSpec } from "../types.js";
import type { AgentConfig } from "../config.js";

test("mathgen: cpi_base_effect reproduces the required-MoM derivation", () => {
  const spec: ResearchSpec = {
    marketAddress: "0x" + "11".repeat(20),
    topic: "test-cpi",
    miningPath: 1,
    langs: ["de"],
    headline: "h",
    figures: ["f1", "f2"],
    sourceDescriptions: ["s"],
    links: [],
    analysis: {
      kind: "cpi_base_effect",
      params: {
        indexName: "x",
        targetMonth: "November",
        targetThresholdPct: 2.8,
        yearAgoYm: "2025-11",
        yearAgoIndex: 115.4,
        series: [["2025-11", 115.4], ["2026-10", 118.2]],
        seasonalMomPct: [0.2, 0.1, 0.5, 0.0, 0.1, -0.1, 0.3, 0.1, 0.2, 0.0],
      },
    },
  };
  const dir = mkdtempSync(join(tmpdir(), "aa-"));
  const res = runAnalysis(spec, join(dir, "data.csv"), "2026-11-26T12:00:00.000Z");
  assert.equal(res.kind, "cpi_base_effect");
  // required MoM = (1.028*115.4/118.2 - 1)*100 = 0.3647... should appear in method text
  assert.ok(res.methodLines.some((l) => l.includes("0.365")), res.methodLines.join("; "));
  assert.ok(res.evidenceImpliedYes > 0 && res.evidenceImpliedYes < 0.3);
  rmSync(dir, { recursive: true, force: true });
});

test("mathgen: markov_lead — a 0.5 lead only fails if the leader loses", () => {
  const spec: ResearchSpec = {
    marketAddress: "0x" + "22".repeat(20),
    topic: "test-markov",
    miningPath: 2,
    langs: ["en"],
    headline: "h",
    figures: ["f1", "f2"],
    sourceDescriptions: ["s"],
    links: [],
    analysis: {
      kind: "markov_lead",
      params: {
        asOfGame: 7,
        leader: "A",
        leaderPoints: 4.0,
        trailer: "B",
        trailerPoints: 3.5,
        games: [{ leaderColor: "White", winProb: 0.3, drawProb: 0.55, lossProb: 0.15 }],
        historicalBasis: "test",
      },
    },
  };
  const dir = mkdtempSync(join(tmpdir(), "aa-"));
  const res = runAnalysis(spec, join(dir, "data.csv"), "2026-11-26T12:00:00.000Z");
  assert.ok(Math.abs(res.evidenceImpliedYes - 0.85) < 1e-9);
  rmSync(dir, { recursive: true, force: true });
});

test("verifySources: expect substrings must be present in scraped content", async () => {
  const cfg = { mode: "mock", liveSubmit: false } as unknown as AgentConfig;
  const firecrawl = createFirecrawl(cfg);
  const url = Object.keys(SCRAPE_FIXTURES)[0]!;
  const spec: ResearchSpec = {
    marketAddress: "0x" + "33".repeat(20),
    topic: "test-verify",
    miningPath: 3,
    langs: ["de"],
    headline: "h",
    figures: ["f1", "f2"],
    sourceDescriptions: ["s"],
    links: [
      { url, label: "l", lang: "de", access: "scraped", expect: ["VPI"] },
    ],
  };
  const ok = await verifySources(spec, firecrawl);
  assert.equal(ok.ok, true, JSON.stringify(ok.failures));
  const bad: ResearchSpec = {
    ...spec,
    links: [{ url, label: "l", lang: "de", access: "scraped", expect: ["NOT-PRESENT-STRING"] }],
  };
  const fail = await verifySources(bad, firecrawl);
  assert.equal(fail.ok, false);
  assert.equal(fail.failures[0]!.missing[0], "NOT-PRESENT-STRING");
});

test("submitter guard: mode=mock config can never enable liveSubmit", async () => {
  const { resolveConfig } = await import("../config.js");
  delete process.env.DELPHI_API_ACCESS_KEY;
  delete process.env.LIVE_SUBMIT;
  const cfg = resolveConfig({ mode: "mock", liveSubmit: true });
  assert.equal(cfg.liveSubmit, false);
  assert.equal(cfg.mode, "mock");
});

test("submitDraft refuses without the triple guard", async () => {
  const dir = mkdtempSync(join(tmpdir(), "aa-"));
  writeFileSync(join(dir, "manifest.json"), "{}");
  const { submitDraft, SubmitGuardError } = await import("../submitter.js");
  const cfg = { mode: "live", liveSubmit: false } as unknown as AgentConfig;
  await assert.rejects(() => submitDraft(cfg, dir), SubmitGuardError);
  rmSync(dir, { recursive: true, force: true });
});

import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { randomUUID } from "node:crypto";
import type { CompetitionMarket, DraftManifest, EvidenceCandidate } from "./types.js";

/**
 * Draft writer. One directory per submission under drafts/:
 *   note.md      — the exact 4-part dated note text that would be submitted
 *   data.csv     — compact machine-readable series backing section 3 (written by mathgen)
 *   manifest.json — links, files, stance, idempotency key, submission state
 * The note is a 4-part dated note per the competition guide: dated fact,
 * sources, method, forecast comparison. All key figures are pasted inline so
 * the judge never needs JS rendering (anti-`unverifiable`).
 */

export interface DraftPaths {
  dir: string;
  note: string;
  csv: string;
  manifest: string;
}

export function draftDirFor(runDate: string, topic: string): DraftPaths {
  const dir = join("drafts", `${runDate}-${topic}`);
  return {
    dir,
    note: join(dir, "note.md"),
    csv: join(dir, "data.csv"),
    manifest: join(dir, "manifest.json"),
  };
}

export function composeNote(c: EvidenceCandidate, market: CompetitionMarket): string {
  const pct = (p: number) => (p < 0.001 ? `<0.1%` : `${(p * 100).toFixed(1)}%`);
  const impliedPct = pct(c.analysis.evidenceImpliedYes);
  const marketPct = `${(c.marketImpliedYes * 100).toFixed(1)}%`;
  const push = c.stance === "yes" ? "up" : "down";
  const lines: string[] = [];
  lines.push(`Evidence note — ${c.asOf.slice(0, 10)} (all times UTC)`);
  lines.push("");
  lines.push(`Market: ${market.question}`);
  lines.push(`Market address: ${market.address} — evidence cutoff ${market.evidenceCutoffAt}`);
  lines.push("");
  lines.push("1) DATED FACT");
  lines.push(c.headline);
  lines.push("");
  lines.push("Key figures, copied from the source content at fetch time (also in data.csv):");
  for (const f of c.figures) lines.push(`- ${f}`);
  lines.push("");
  lines.push("2) SOURCES");
  c.links.forEach((l, i) => {
    lines.push(`- [${i + 1}] ${l.url} — ${c.sourceDescriptions[i] ?? l.label} (${l.lang}, ${l.access})`);
  });
  lines.push(
    "- data.csv (attached) holds the full series/derivation table in machine-readable form; every figure above also appears inline so nothing depends on JS or bot-walled pages.",
  );
  lines.push("");
  lines.push("3) METHOD");
  for (const m of c.analysis.methodLines) lines.push(`- ${m}`);
  lines.push("");
  lines.push("4) FORECAST COMPARISON");
  lines.push(`- Market implied P(yes) at snapshot: ${marketPct}%`);
  lines.push(
    `- This evidence implies P(yes) ≈ ${impliedPct}% (confidence: ${c.analysis.confidence}) — it pushes the ${c.stance.toUpperCase()} side ${push}.`,
  );
  lines.push(
    `- Stance: ${c.stance.toUpperCase()} side only. No evidence is submitted for the opposite side of this market.`,
  );
  return lines.join("\n") + "\n";
}

export function writeDraft(
  c: EvidenceCandidate,
  market: CompetitionMarket,
  mode: "mock" | "live",
  runDate: string,
): DraftPaths {
  const paths = draftDirFor(runDate, c.topic);
  mkdirSync(paths.dir, { recursive: true });
  const manifest: DraftManifest = {
    topic: c.topic,
    marketAddress: c.marketAddress,
    marketQuestion: c.marketQuestion,
    generatedAt: new Date().toISOString(),
    mode,
    asOf: c.asOf,
    stance: c.stance,
    links: c.links.map((l) => l.url),
    files: ["data.csv"],
    factSignature: c.factSignature,
    idempotencyKey: randomUUID(),
    submittedAt: null,
    submissionId: null,
  };
  writeFileSync(paths.note, composeNote(c, market), "utf-8");
  writeFileSync(paths.manifest, JSON.stringify(manifest, null, 2), "utf-8");
  return paths;
}

